    case focus(FocusSettings)
    case models(ModelSettings)
    case voice(VoiceSettings)
    case computer(ComputerSettings)
    case memory(MemorySettings)

    private enum CodingKeys: String, CodingKey {
        case tag = "section"
        case content = "value"
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let tag = try c.decode(String.self, forKey: .tag)
        switch tag {
        case "general": self = .general(try c.decode(GeneralSettings.self, forKey: .content))
        case "appearance": self = .appearance(try c.decode(AppearanceSettings.self, forKey: .content))
        case "privacy": self = .privacy(try c.decode(PrivacySettings.self, forKey: .content))
        case "onboarding": self = .onboarding(try c.decode(OnboardingSettings.self, forKey: .content))
        case "invocation": self = .invocation(try c.decode(InvocationSettings.self, forKey: .content))
        case "cursor": self = .cursor(try c.decode(CursorSettings.self, forKey: .content))
        case "focus": self = .focus(try c.decode(FocusSettings.self, forKey: .content))
        case "models": self = .models(try c.decode(ModelSettings.self, forKey: .content))
        case "voice": self = .voice(try c.decode(VoiceSettings.self, forKey: .content))
        case "computer": self = .computer(try c.decode(ComputerSettings.self, forKey: .content))
        case "memory": self = .memory(try c.decode(MemorySettings.self, forKey: .content))
        default:
            throw DecodingError.dataCorruptedError(forKey: .tag, in: c, debugDescription: "unknown SettingsSection variant \(tag)")
        }
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        switch self {
        case .general(let v):
            try c.encode("general", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .appearance(let v):
            try c.encode("appearance", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .privacy(let v):
            try c.encode("privacy", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .onboarding(let v):
            try c.encode("onboarding", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .invocation(let v):
            try c.encode("invocation", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .cursor(let v):
            try c.encode("cursor", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .focus(let v):
            try c.encode("focus", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .models(let v):
            try c.encode("models", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .voice(let v):
            try c.encode("voice", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .computer(let v):
            try c.encode("computer", forKey: .tag)
            try c.encode(v, forKey: .content)
        case .memory(let v):
            try c.encode("memory", forKey: .tag)
            try c.encode(v, forKey: .content)
        }
    }
}

